import type { ToolDescriptor } from "./stable-prefix.js";
import { DEFAULT_TOOL_DESCRIPTORS_A } from "./default-tool-descriptors-a.js";
import { DEFAULT_TOOL_DESCRIPTORS_B } from "./default-tool-descriptors-b.js";
import { attachDefaultArgsJsonSchema } from "./default-tool-args-schemas.js";

/**
 * Default tool descriptors. `argsSchema` uses a compact TS-like form
 * that the LLM reads via the stable prefix; `argsJsonSchema` carries
 * the structured shape used by the cloud `native_tools` transport
 * (see `default-tool-args-schemas.ts`). The two are kept in sync by
 * convention — the JSON Schema is authoritative for validation, the
 * text is authoritative for prompt rendering.
 *
 * `tier: "rare"` tools render as one-line manifests; use `tool.view`
 * to load the full schema into `### loaded-tools`.
 */
export const DEFAULT_TOOL_DESCRIPTORS: readonly ToolDescriptor[] = [
  ...DEFAULT_TOOL_DESCRIPTORS_A,
  ...DEFAULT_TOOL_DESCRIPTORS_B,
].map(attachDefaultArgsJsonSchema);

const TOOL_DESCRIPTOR_BY_NAME: ReadonlyMap<string, ToolDescriptor> = new Map(
  DEFAULT_TOOL_DESCRIPTORS.map((d) => [d.name, d] as const),
);

export function getToolDescriptorByName(
  name: string,
): ToolDescriptor | undefined {
  return TOOL_DESCRIPTOR_BY_NAME.get(name);
}

export function isRareToolName(name: string): boolean {
  return getToolDescriptorByName(name)?.tier === "rare";
}

/**
 * Which registered tools READ the filesystem, and which of their
 * arguments name what they read. Shared by the session read scope and
 * the narrower fusion-worker one (`read-scope.ts`).
 */

export type ReadTargetsOf = (args: Record<string, unknown>) => string[];

function nonEmpty(value: unknown): string | undefined {
  return typeof value === "string" && value.length > 0 ? value : undefined;
}

const pathArg: ReadTargetsOf = (args) => {
  const path = nonEmpty(args.path);
  return path === undefined ? [] : [path];
};

/**
 * The read-class filesystem tools and the argument(s) naming what they
 * read. A search tool's omitted root is the working directory, which is
 * inside by definition, so it contributes nothing to check.
 */
export const READ_TOOL_TARGETS: ReadonlyMap<string, ReadTargetsOf> = new Map<
  string,
  ReadTargetsOf
>([
  ["os.fs.read", pathArg],
  ["os.fs.list", pathArg],
  ["os.fs.hash", pathArg],
  ["os.fs.watch", pathArg],
  ["os.fs.read_document", pathArg],
  ["os.fs.archive.list", pathArg],
  ["os.fs.archive.read_entry", pathArg],
  ["os.fs.grep", pathArg],
  [
    "os.fs.glob",
    // `cwd` wins over `path` inside the tool; either names the root.
    (args) => {
      const root = nonEmpty(args.cwd) ?? nonEmpty(args.path);
      return root === undefined ? [] : [root];
    },
  ],
  [
    "os.fs.diff",
    (args) =>
      [nonEmpty(args.aPath), nonEmpty(args.bPath)].filter(
        (path): path is string => path !== undefined,
      ),
  ],
  [
    "vision.describe",
    (args) =>
      [
        nonEmpty(args.path),
        ...(Array.isArray(args.paths) ? args.paths.map(nonEmpty) : []),
      ].filter((path): path is string => path !== undefined),
  ],
  [
    // A syntax check reads every file it is handed.
    "verify.syntax",
    (args) =>
      (Array.isArray(args.files) ? args.files.map(nonEmpty) : []).filter(
        (path): path is string => path !== undefined,
      ),
  ],
]);

/** The shell tool, checked by token rather than by a named argument. */
export const SHELL_TOOL = "os.shell.run";

/** `https://…`, `data:…` — not a filesystem path, not this module's business. */
export const URL_LIKE = /^[a-z][a-z0-9+.-]*:(?:\/\/|[^\\/])/i;

import type { DangerousToolOptions } from "../../approval/dangerous-tool.js";
import type { ReadScope } from "../../config/index.js";
import { isFusionWorkerSessionId } from "../../session/fusion-worker-session.js";
import type { ToolDefinition, ToolRegistry } from "../tool-registry.js";
import {
  checkWorkerRead,
  findSessionReadOutside,
  workerReadRefusal,
} from "./read-scope.js";
import {
  ReadOutsideApprover,
  readOutsidePrompt,
  shellReadOutsidePrompt,
} from "./read-scope-approval.js";
import {
  findShellPathOutsideScope,
  shellCommandLine,
  type ShellScopeEnv,
} from "./read-scope-shell.js";
import { READ_TOOL_TARGETS, SHELL_TOOL } from "./read-scope-targets.js";

export interface ConfineReadsOptions {
  /** The directories a fusion worker's fan-out may write in. */
  grantedDirs: (sessionId: string) => readonly string[];
  /**
   * The live `agent.readScope`. Read on every call, so a config change
   * takes effect without a restart. Omitted: only fusion workers are
   * confined and the shell is not wrapped — the pre-v67 install
   * (`confineWorkerReads`).
   */
  readScope?: () => ReadScope;
  /**
   * The ladder a read outside the scope asks through (`fs_read_outside`,
   * `read-scope-approval.ts`). Required with `readScope`: the session
   * scope is a question, and a question needs a gate — an install that
   * forgot the gate would silently be a refusal, which is exactly the
   * half-wiring the throw below exists to catch.
   */
  approvals?: DangerousToolOptions;
  /** The shell check's notion of home and platform; a test seam. */
  shellEnv?: ShellScopeEnv;
}

/** Definitions this module produced, so a second install does not wrap twice. */
const CONFINED = new WeakSet<ToolDefinition>();

/**
 * Wrap every registered read-class tool (and, under a session scope, the
 * shell) so a call is checked before it runs. Call once, after the
 * native tools are registered. Returns the names it confined.
 *
 * Wrapping at the registry rather than inside each tool keeps the rule
 * in one place, and `registry.invoke` is the single path every call —
 * native, batched, or recovered from text — takes. A worker session
 * gets the worker check first (always on, a refusal); then, when the
 * scope is `working-dir`, every other session's call outside the roots
 * is asked about, and runs or is refused by the answer.
 */
export function confineReads(
  registry: Pick<ToolRegistry, "has" | "get" | "register">,
  options: ConfineReadsOptions,
): string[] {
  if (options.readScope !== undefined && options.approvals === undefined) {
    throw new Error(
      "confineReads: a session read scope asks through the approval ladder; pass `approvals` with `readScope`",
    );
  }
  const asker =
    options.approvals === undefined
      ? null
      : new ReadOutsideApprover(options.approvals);
  const confined: string[] = [];
  const scoped = () => options.readScope?.() === "working-dir";
  const install = (name: string, run: ToolDefinition["run"]): void => {
    const inner = registry.get(name);
    confined.push(name);
    if (CONFINED.has(inner)) return;
    const wrapped: ToolDefinition = { ...inner, run };
    CONFINED.add(wrapped);
    registry.register(wrapped);
  };

  for (const name of READ_TOOL_TARGETS.keys()) {
    if (!registry.has(name)) continue;
    const inner = registry.get(name);
    install(name, async (args, ctx) => {
      const worker = checkWorkerRead(
        name,
        args,
        ctx,
        options.grantedDirs(ctx.sessionId),
      );
      if (worker !== null) return worker;
      if (asker === null || !scoped()) return inner.run(args, ctx);
      const refusal = await asker.admit(
        name,
        ctx,
        (roots) => findSessionReadOutside(name, args, ctx, roots),
        (path, root) => readOutsidePrompt(path, ctx.workingDir, root),
      );
      return refusal ?? inner.run(args, ctx);
    });
  }

  if (asker !== null && registry.has(SHELL_TOOL)) {
    const inner = registry.get(SHELL_TOOL);
    install(SHELL_TOOL, async (args, ctx) => {
      if (!scoped()) return inner.run(args, ctx);
      if (isFusionWorkerSessionId(ctx.sessionId)) {
        // A worker's world is its task's directories, and there is
        // nobody to ask: the refusal, as for its reads.
        const granted = options.grantedDirs(ctx.sessionId);
        const outside = findShellPathOutsideScope(
          args,
          ctx,
          [ctx.workingDir, ...granted],
          options.shellEnv,
        );
        return outside === null
          ? inner.run(args, ctx)
          : workerReadRefusal(SHELL_TOOL, outside, ctx, granted);
      }
      const refusal = await asker.admit(
        SHELL_TOOL,
        ctx,
        (roots) => findShellPathOutsideScope(args, ctx, roots, options.shellEnv),
        (path, root) =>
          shellReadOutsidePrompt(
            shellCommandLine(args),
            path,
            ctx.workingDir,
            root,
          ),
      );
      return refusal ?? inner.run(args, ctx);
    });
  }
  return confined;
}

/**
 * The fusion-only install: workers confined to their working directory
 * and fan-out scope, every other session untouched, the shell not
 * wrapped. Kept for callers that want exactly that; the runtime installs
 * `confineReads` with the live `agent.readScope` and the ladder instead.
 */
export function confineWorkerReads(
  registry: Pick<ToolRegistry, "has" | "get" | "register">,
  options: { grantedDirs: (sessionId: string) => readonly string[] },
): string[] {
  return confineReads(registry, { grantedDirs: options.grantedDirs });
}

/**
 * A tool set per role.
 *
 * Every turn used to see every tool: a fusion worker got the whole
 * catalog minus nine names (about 85 built-ins, described twice on a
 * native-tool provider — as prompt text and as JSON schemas — so run
 * 14's worker prompts opened at ~13.8K tokens), and the local grammar
 * enumerated ~80 names for every role. A role names the tools a turn
 * is FOR: a builder reads, writes, runs and checks; an orchestrator
 * reads, checks, delegates and replies; a normal turn keeps everything.
 *
 * A role shapes three things, once per transport:
 *  - the `### tools` block lists the role's tools in full (frequent) or
 *    as one-liners (rare) and the rest as ONE line of names, "also
 *    available via tool.view" — so the prefix is per role, not per
 *    turn, and a role change is one cold read;
 *  - a native-tool provider receives the role's tools as JSON schemas
 *    (plus what the session has loaded), not the whole catalog;
 *  - the local grammar admits the role's names (plus loaded ones).
 *
 * A tool outside the role is not gone: `tool.view { name }` loads its
 * descriptor into `### loaded-tools`, after which it is described,
 * callable and in the grammar. That costs a step, which is the point —
 * the common case pays nothing for the long tail.
 *
 * The sets are NAMES, checked by predicate, so a role tolerates a tool
 * that is not registered in this build (`verify.*` lands from another
 * package; an MCP server may or may not be connected). A name a role
 * admits but no registry holds is simply never a descriptor.
 */

export type ToolRole = "builder" | "orchestrator" | "full";

export const TOOL_ROLES: readonly ToolRole[] = ["builder", "orchestrator", "full"];

/** The terminals and the two discovery tools every role keeps. */
const REPLY = "reply";
const FINISH = "finish";

/**
 * `os.fs.*` tools that only read. The orchestrator's whole filesystem
 * surface, and the read half of the builder's.
 */
const FS_READ_TOOLS: readonly string[] = [
  "os.fs.read",
  "os.fs.read_document",
  "os.fs.list",
  "os.fs.glob",
  "os.fs.grep",
  "os.fs.hash",
  "os.fs.diff",
  "os.fs.watch",
  "os.fs.locate_project",
  "os.fs.archive.list",
  "os.fs.archive.read_entry",
];

/** `os.fs.*` tools that change the working tree. Builder only. */
const FS_WRITE_TOOLS: readonly string[] = [
  "os.fs.write",
  "os.fs.edit",
  "os.fs.patch",
  // Undoes one of the three; a worker that shrank a user file must be
  // able to put it back.
  "os.fs.restore",
];

/** Long-term memory READS: the orchestrator plans against what is known. */
const MEMORY_READ_TOOLS: readonly string[] = [
  "memory.profile.list",
  "memory.profile.history",
  "memory.notes.recall",
  "memory.lessons.recall",
  "memory.procedures.recall",
];

interface RoleSpec {
  names: ReadonlySet<string>;
  /** Name prefixes admitted wholesale (`verify.` admits `verify.syntax`). */
  prefixes: readonly string[];
}

/**
 * A builder does the work: files in and out, a shell, the checks that
 * prove the work runs, the two discovery tools, and every MCP tool
 * (an MCP server is mounted precisely so a worker can use it). No
 * `finish` — a worker ending its own throwaway session is read the
 * same as a reply, and a normal turn is not a builder.
 */
const BUILDER: RoleSpec = {
  names: new Set([
    ...FS_READ_TOOLS.filter(
      (name) =>
        name !== "os.fs.locate_project" && !name.startsWith("os.fs.archive."),
    ),
    ...FS_WRITE_TOOLS,
    "os.shell.run",
    "tool.view",
    "skill.view",
    REPLY,
  ]),
  prefixes: ["verify.", "mcp."],
};

/**
 * An orchestrator plans, checks and delegates; it never builds (the
 * fusion gate refuses every mutation anyway — see
 * `fusion-orchestrator-mode.ts`). D1: read-only verification is its
 * to run. No MCP tools: the gate treats them as mutating, so listing
 * them would only advertise refusals.
 */
const ORCHESTRATOR: RoleSpec = {
  names: new Set([
    ...FS_READ_TOOLS,
    ...MEMORY_READ_TOOLS,
    "fusion.delegate",
    "tool.view",
    REPLY,
    FINISH,
  ]),
  prefixes: ["verify."],
};

/** Does `role` list `name` — i.e. describe it in full and admit it unloaded? */
export function roleAdmits(role: ToolRole, name: string): boolean {
  if (role === "full") return true;
  const spec = role === "builder" ? BUILDER : ORCHESTRATOR;
  if (spec.names.has(name)) return true;
  return spec.prefixes.some((prefix) => name.startsWith(prefix));
}

/**
 * Split descriptors into the role's own and the rest. `full` (and an
 * absent role) keeps everything on the inside, so a caller that
 * partitions unconditionally renders byte-identical output for it.
 */
export function partitionByRole<T extends { name: string }>(
  role: ToolRole | undefined,
  descriptors: readonly T[],
): { inRole: T[]; outside: T[] } {
  if (role === undefined || role === "full") {
    return { inRole: [...descriptors], outside: [] };
  }
  const inRole: T[] = [];
  const outside: T[] = [];
  for (const d of descriptors) {
    (roleAdmits(role, d.name) ? inRole : outside).push(d);
  }
  return { inRole, outside };
}

/**
 * The descriptors a step under `role` describes in full and puts on the
 * wire: the role's own, plus any the session has loaded through
 * `tool.view` (`loaded` is their names). Everything else stays reachable
 * by loading it.
 */
export function descriptorsForRole<T extends { name: string }>(
  role: ToolRole | undefined,
  descriptors: readonly T[],
  loaded: ReadonlySet<string>,
): readonly T[] {
  if (role === undefined || role === "full") return descriptors;
  return descriptors.filter(
    (d) => roleAdmits(role, d.name) || loaded.has(d.name),
  );
}

